use super::{conversion::Segment, extras, learning::Learned};
use std::{collections::HashMap, sync::LazyLock};

// Group by the first letter while preserving each group's longest-first order.
const KANA: &str = include_str!("romaji.txt");
// Generated by tools/build_dictionary.py from the Mozc open source dictionary.
const WORDS: &str = include_str!("dictionary.tsv");
// Symbols, kaomoji and emoji by reading, from the same script.
const SYMBOLS: &str = include_str!("symbols.tsv");
/// Words of one clause, not counting the symbols and the plain kana forms.
const MAX_CANDIDATES: usize = 40;
/// Words offered for the start of a longer reading.
pub const MAX_PREDICTIONS: usize = 8;
/// Readings that are rarer than this are not trusted to tell a typo from a word
/// or to split clauses.
const COMMON_COST: u32 = 6000;
// Words that follow a noun inside one clause (文節).
const PARTICLES: &[&str] = &[
    "から",
    "まで",
    "より",
    "だけ",
    "ほど",
    "など",
    "って",
    "でも",
    "には",
    "とは",
    "では",
    "のは",
    "ので",
    "のに",
    "けど",
    "ですが",
    "でした",
    "です",
    "だった",
    "だ",
    "は",
    "が",
    "を",
    "に",
    "へ",
    "で",
    "と",
    "も",
    "の",
    "や",
    "か",
    "ね",
    "よ",
    "な",
    "わ",
    "ぞ",
    "さ",
    "し",
    "ば",
    "ぜ",
];
type RomanSyllable = (&'static str, &'static str);

/// What the dictionary knows about one reading.
#[derive(Clone, Copy)]
struct Entry {
    /// The lowest cost of its words. Lower is more common.
    cost: u32,
    /// Space separated `kind + surface` tokens, the most likely first.
    tokens: &'static str,
}

impl Entry {
    /// The most likely complete word, which is not a verb stem.
    fn word(self) -> Option<&'static str> {
        self.tokens
            .split(' ')
            .find(|token| !token.starts_with('v'))
            .and_then(|token| token.get(1..))
    }
}

static INDEX: LazyLock<HashMap<&'static str, Entry>> = LazyLock::new(|| {
    WORDS
        .lines()
        .filter_map(|line| {
            let mut fields = line.splitn(3, '\t');
            let reading = fields.next()?;
            let cost = fields.next()?.parse().ok()?;
            Some((
                reading,
                Entry {
                    cost,
                    tokens: fields.next()?,
                },
            ))
        })
        .collect()
});
static SYMBOL_INDEX: LazyLock<HashMap<&'static str, &'static str>> = LazyLock::new(|| {
    SYMBOLS
        .lines()
        .filter_map(|line| line.split_once('\t'))
        .collect()
});
static SYLLABLES: LazyLock<[Vec<RomanSyllable>; 26]> = LazyLock::new(|| {
    let mut groups: [Vec<RomanSyllable>; 26] = Default::default();
    for (roman, kana) in KANA
        .split_ascii_whitespace()
        .filter_map(|entry| entry.split_once('='))
    {
        groups[(roman.as_bytes()[0] - b'a') as usize].push((roman, kana));
    }
    groups
});

pub fn kana(input: &str, finalizing: bool) -> String {
    let mut result = String::new();
    let lowercase = input.to_ascii_lowercase();
    let mut rest = lowercase.as_str();
    while let Some(&first) = rest.as_bytes().first() {
        let next = rest.as_bytes().get(1).copied();
        // A bare run of three or more n's is literal. Keep the explicit nn and n'
        // rules and normal syllables such as the nn in こんにちは.
        if rest.starts_with("nnn") {
            let len = rest.bytes().take_while(|&byte| byte == b'n').count();
            if rest
                .as_bytes()
                .get(len)
                .is_none_or(|byte| !byte.is_ascii_alphabetic() && *byte != b'\'')
            {
                let offset = input.len() - rest.len();
                result.push_str(&input[offset..offset + len]);
                rest = &rest[len..];
                continue;
            }
        }
        if first == b'n' {
            match next {
                Some(b'n')
                    if rest
                        .as_bytes()
                        .get(2)
                        .is_some_and(|next| b"aiueoy".contains(next)) =>
                {
                    result.push('ん');
                    rest = &rest[1..];
                    continue;
                }
                Some(b'n' | b'\'') => {
                    result.push('ん');
                    rest = &rest[2..];
                    continue;
                }
                Some(next) if next.is_ascii_alphabetic() && !b"aiueoy".contains(&next) => {
                    result.push('ん');
                    rest = &rest[1..];
                    continue;
                }
                None if finalizing => {
                    result.push('ん');
                    break;
                }
                Some(next) if !next.is_ascii_alphabetic() => {
                    result.push('ん');
                    rest = &rest[1..];
                    continue;
                }
                _ => {}
            }
        }
        if next == Some(first)
            && first.is_ascii_lowercase()
            && !b"aiueon".contains(&first)
            && syllable(&rest[1..]).is_some()
        {
            result.push('っ');
            rest = &rest[1..];
            continue;
        }
        if let Some((roman, kana)) = syllable(rest) {
            result.push_str(kana);
            rest = &rest[roman.len()..];
        } else {
            let ch = input[input.len() - rest.len()..].chars().next().unwrap();
            result.push(key_label(ch));
            rest = &rest[ch.len_utf8()..];
        }
    }
    result
}

pub fn key_label(key: char) -> char {
    match key {
        ',' => '、',
        '.' => '。',
        '-' => 'ー',
        '[' => '「',
        ']' => '」',
        '¥' => '￥',
        key if key.is_ascii_punctuation() => char::from_u32(key as u32 + 0xfee0).unwrap(),
        _ => key,
    }
}

fn syllable(rest: &str) -> Option<RomanSyllable> {
    let first = *rest.as_bytes().first()?;
    if !first.is_ascii_lowercase() {
        return None;
    }
    SYLLABLES[(first - b'a') as usize]
        .iter()
        .copied()
        .find(|(roman, _)| rest.starts_with(roman))
}

pub fn katakana(value: &str) -> String {
    value
        .chars()
        .map(|c| match c {
            'ぁ'..='ゖ' => char::from_u32(c as u32 + 0x60).unwrap(),
            _ => c,
        })
        .collect()
}

pub fn halfwidth(value: &str) -> String {
    const KANA: &str = "ヲァィゥェォャュョッーアイウエオカキクケコサシスセソタチツテトナニヌネノハヒフヘホマミムメモヤユヨラリルレロワン";
    const VOICED: &str = "ガギグゲゴザジズゼゾダヂヅデドバビブベボヴヷヺ";
    const BASE: &str = "カキクケコサシスセソタチツテトハヒフヘホウワヲ";
    const SEMIVOICED: &str = "パピプペポ";

    let mut result = String::new();
    for ch in value.chars() {
        let (base, mark) = if let Some(index) = VOICED.chars().position(|voiced| voiced == ch) {
            (BASE.chars().nth(index).unwrap(), Some('ﾞ'))
        } else if let Some(index) = SEMIVOICED.chars().position(|voiced| voiced == ch) {
            ("ハヒフヘホ".chars().nth(index).unwrap(), Some('ﾟ'))
        } else {
            (ch, None)
        };
        let narrow = match base {
            '、' => ',',
            '。' => '.',
            '「' => '｢',
            '」' => '｣',
            '・' => '･',
            '\u{3099}' | '゛' => 'ﾞ',
            '\u{309a}' | '゜' => 'ﾟ',
            '￥' => '¥',
            '！'..='～' => char::from_u32(base as u32 - 0xfee0).unwrap(),
            _ => KANA
                .chars()
                .position(|kana| kana == base)
                .and_then(|index| char::from_u32(0xff66 + index as u32))
                .unwrap_or(base),
        };
        result.push(narrow);
        result.extend(mark);
    }
    result
}

pub fn with_ascii_brackets(halfwidth: &str) -> Option<String> {
    halfwidth
        .contains(['｢', '｣'])
        .then(|| halfwidth.replace('｢', "[").replace('｣', "]"))
}

/// Loads the dictionary index now so that the first conversion does not stall.
pub fn warm_up() {
    LazyLock::force(&INDEX);
    LazyLock::force(&READINGS);
    LazyLock::force(&SYMBOL_INDEX);
}

/// Dictionary readings in byte order, for prefix lookups.
static READINGS: LazyLock<Vec<(&'static str, Entry)>> = LazyLock::new(|| {
    let mut readings: Vec<_> = INDEX
        .iter()
        .map(|(reading, entry)| (*reading, *entry))
        .collect();
    readings.sort_unstable_by_key(|(reading, _)| *reading);
    readings
});

/// The readings that start with `prefix`, in byte order.
fn readings_starting_with(prefix: &str) -> impl Iterator<Item = (&'static str, Entry)> + '_ {
    let at = READINGS.partition_point(|(known, _)| *known < prefix);
    READINGS[at..]
        .iter()
        .take_while(move |(known, _)| known.starts_with(prefix))
        .copied()
}
static KANA_ALPHABET: LazyLock<Vec<char>> = LazyLock::new(|| ('ぁ'..='ゖ').chain(['ー']).collect());

/// Shortest and longest tail of a typed reading that is checked for typos.
const MIN_TAIL: usize = 3;
const MAX_TAIL: usize = 12;
const MAX_CORRECTIONS: usize = 4;

pub fn is_reading_char(ch: char) -> bool {
    matches!(ch, 'ぁ'..='ゖ' | 'ー')
}

/// Whether `reading` is a dictionary reading or the start of one, which means
/// it is either correct or still being typed.
fn plausible_reading(reading: &str) -> bool {
    readings_starting_with(reading).any(|(_, entry)| entry.cost <= COMMON_COST)
}

/// Whether `reading` is a word that people use, not a rare one that only
/// makes a reading look valid.
fn is_common_reading(reading: &str) -> bool {
    INDEX
        .get(reading)
        .is_some_and(|entry| entry.cost <= COMMON_COST)
}

/// Dictionary readings one edit away from `chars`: a swap of neighbours, a
/// missing letter, an extra letter or a wrong letter.
fn one_edit_readings(chars: &[char]) -> Vec<String> {
    let original: String = chars.iter().collect();
    let mut found: Vec<(u8, u32, String)> = Vec::new();
    let mut consider = |rank: u8, edited: &[char]| {
        let candidate: String = edited.iter().collect();
        if candidate != original
            && !found.iter().any(|(_, _, known)| *known == candidate)
            && let Some(entry) = INDEX.get(candidate.as_str())
            && entry.cost <= COMMON_COST
        {
            found.push((rank, entry.cost, candidate));
        }
    };
    let mut edited = chars.to_vec();
    for index in 0..chars.len().saturating_sub(1) {
        edited.swap(index, index + 1);
        consider(0, &edited);
        edited.swap(index, index + 1);
    }
    for index in 0..=chars.len() {
        for &letter in KANA_ALPHABET.iter() {
            edited.insert(index, letter);
            consider(1, &edited);
            edited.remove(index);
        }
    }
    // The first letter may belong to the word before the tail, so it is not
    // offered for deletion.
    for index in 1..chars.len() {
        let letter = edited.remove(index);
        consider(2, &edited);
        edited.insert(index, letter);
    }
    for index in 0..chars.len() {
        let letter = edited[index];
        for &other in KANA_ALPHABET.iter().filter(|&&other| other != letter) {
            edited[index] = other;
            consider(3, &edited);
        }
        edited[index] = letter;
    }
    // Without word frequencies there is no telling which kind of slip is most
    // likely, so take the best of each kind in turn. The more common words
    // come first within a kind.
    found.sort_by(|a, b| a.1.cmp(&b.1).then(a.2.cmp(&b.2)));
    let mut ranked = Vec::new();
    for round in 0.. {
        let before = ranked.len();
        for kind in 0..4 {
            if let Some((_, _, candidate)) =
                found.iter().filter(|(rank, ..)| *rank == kind).nth(round)
            {
                ranked.push(candidate.clone());
            }
        }
        if ranked.len() == before || ranked.len() >= MAX_CORRECTIONS {
            break;
        }
    }
    ranked.truncate(MAX_CORRECTIONS);
    ranked
}

/// Looks for a mistyped word at the end of `run`, a run of hiragana. Returns the
/// byte length of that tail and the dictionary readings it may have meant.
/// The longest tail wins; a tail that is, or may become, a dictionary reading is
/// not a typo.
pub fn reading_corrections(run: &str) -> Option<(usize, Vec<String>)> {
    let chars: Vec<char> = run.chars().collect();
    for length in (MIN_TAIL..=chars.len().min(MAX_TAIL)).rev() {
        let tail = &chars[chars.len() - length..];
        let text: String = tail.iter().collect();
        if plausible_reading(&text) {
            return None;
        }
        let corrections = one_edit_readings(tail);
        if !corrections.is_empty() {
            return Some((text.len(), corrections));
        }
    }
    None
}

/// Words with exactly this reading as `(is_inflected_form, surface)`.
fn entries(reading: &str) -> impl Iterator<Item = (bool, &'static str)> {
    INDEX
        .get(reading)
        .into_iter()
        .flat_map(|entry| entry.tokens.split(' '))
        .filter_map(|token| {
            let surface = token.get(1..)?;
            Some((token.starts_with('v'), surface))
        })
}

/// Whole-reading candidates for the prediction bar while the user is typing.
pub fn dictionary(reading: &str) -> impl Iterator<Item = &'static str> {
    let mut seen = Vec::new();
    entries(reading)
        .map(|(_, surface)| surface)
        .filter(move |surface| {
            let fresh = !seen.contains(surface);
            seen.push(*surface);
            fresh
        })
}

/// Symbols, kaomoji and emoji that are typed as `reading`, such as まる → ○.
pub fn symbols(reading: &str) -> impl Iterator<Item = &'static str> {
    SYMBOL_INDEX
        .get(reading)
        .into_iter()
        .flat_map(|symbols| symbols.split(' '))
}

/// Words for the start of a longer reading as `(reading, surface)`, the most
/// common first. A reading that is only a fragment of words has none.
pub fn predictions(prefix: &str, limit: usize) -> Vec<(&'static str, &'static str)> {
    if prefix.is_empty() || !prefix.chars().all(is_reading_char) {
        return Vec::new();
    }
    let mut found: Vec<(u32, &'static str, &'static str)> = readings_starting_with(prefix)
        .filter(|(reading, _)| reading.len() > prefix.len())
        .filter_map(|(reading, entry)| Some((entry.cost, reading, entry.word()?)))
        .collect();
    found.sort_unstable_by(|a, b| {
        a.0.cmp(&b.0)
            .then(a.1.len().cmp(&b.1.len()))
            .then(a.1.cmp(b.1))
    });
    let mut words: Vec<(&str, &str)> = Vec::new();
    for (_, reading, surface) in found {
        if words.len() >= limit {
            break;
        }
        if !words.iter().any(|(_, known)| *known == surface) {
            words.push((reading, surface));
        }
    }
    words
}

/// The reading that `text` is a word of, when it was chosen for the typed
/// `reading`. It is longer than `reading` if `text` was a prediction. None if
/// `text` is not a word of any reading to learn, such as today's date.
pub fn reading_of(reading: &str, text: &str, learned: &Learned) -> Option<String> {
    let own = entries(reading).any(|(_, surface)| surface == text)
        || symbols(reading).any(|symbol| symbol == text)
        || super::emoji::lookup(reading).any(|entry| entry.symbol == text)
        || learned.exact(reading).contains(&text);
    if own {
        return Some(reading.to_owned());
    }
    let longer = learned
        .prefix(reading, MAX_PREDICTIONS)
        .into_iter()
        .find(|(_, known)| *known == text)
        .map(|(longer, _)| longer);
    longer
        .or_else(|| {
            predictions(reading, MAX_PREDICTIONS)
                .into_iter()
                .find(|(_, surface)| *surface == text)
                .map(|(longer, _)| longer)
        })
        .map(str::to_owned)
}

/// Candidates that depend on the clock, such as today's date for きょう.
pub fn computed(reading: &str) -> Vec<String> {
    extras::now()
        .map(|now| extras::moment(reading, now))
        .unwrap_or_default()
}

fn is_particles(tail: &str) -> bool {
    tail.is_empty()
        || PARTICLES
            .iter()
            .any(|particle| tail.strip_prefix(particle).is_some_and(is_particles))
}

/// Candidates for one clause. `best` is the clause as the sentence-level
/// conversion of the system IME wrote it.
fn clause_candidates(reading: &str, best: Option<&str>, learned: &Learned) -> Vec<String> {
    fn push(candidates: &mut Vec<String>, value: &str) {
        if !value.is_empty() && !candidates.iter().any(|known| known == value) {
            candidates.push(value.to_owned());
        }
    }

    let mut candidates = Vec::new();
    // What the user chose before leads, then the system IME's reading of the sentence.
    for text in learned.exact(reading) {
        push(&mut candidates, text);
    }
    if let Some(best) = best {
        push(&mut candidates, best);
    }
    for (_, surface) in entries(reading) {
        push(&mut candidates, surface);
    }
    let splits: Vec<usize> = reading
        .char_indices()
        .map(|(index, _)| index)
        .skip(1)
        .collect();
    // A head word with a tail: a noun with particles, or an inflected stem with endings.
    for &split in splits.iter().rev() {
        if candidates.len() >= MAX_CANDIDATES {
            break;
        }
        let (head, tail) = reading.split_at(split);
        let nominal = is_particles(tail);
        // A one-letter head of a long clause is almost always noise.
        if split == head.chars().next().map_or(0, char::len_utf8) && !nominal && splits.len() > 2 {
            continue;
        }
        for (_, surface) in entries(head)
            .filter(|(inflected, _)| *inflected != nominal)
            .take(3)
        {
            push(&mut candidates, &format!("{surface}{tail}"));
        }
    }
    candidates.truncate(MAX_CANDIDATES);
    push(&mut candidates, reading);
    let katakana = katakana(reading);
    push(&mut candidates, &katakana);
    let halfwidth = halfwidth(&katakana);
    let ascii_brackets = with_ascii_brackets(&halfwidth);
    if !candidates.contains(&halfwidth) {
        // Typed symbols and letters have no words, so their half-width form leads.
        let at = if reading.chars().all(is_reading_char) {
            candidates.len()
        } else {
            candidates.len().min(2)
        };
        candidates.insert(at, halfwidth);
    }
    if let Some(value) = ascii_brackets {
        push(&mut candidates, &value);
    }
    if reading.chars().all(|ch| ch == 'ー') {
        push(&mut candidates, &"-".repeat(reading.chars().count()));
    }
    for value in computed(reading) {
        push(&mut candidates, &value);
    }
    for symbol in symbols(reading) {
        push(&mut candidates, symbol);
    }
    candidates
}

/// Splits a reading into clauses without the system IME: a dictionary word with
/// the particles that follow it.
fn split_clauses(reading: &str) -> Vec<&str> {
    let mut clauses = Vec::new();
    let mut rest = reading;
    while !rest.is_empty() {
        let is_kana = |ch| matches!(ch, 'ぁ'..='ゖ' | 'ー');
        let kana_run = is_kana(rest.chars().next().unwrap());
        let run_end = rest
            .char_indices()
            .find_map(|(index, ch)| (is_kana(ch) != kana_run).then_some(index))
            .unwrap_or(rest.len());
        if !kana_run {
            clauses.push(&rest[..run_end]);
            rest = &rest[run_end..];
            continue;
        }
        let mut ends: Vec<usize> = rest[..run_end]
            .char_indices()
            .skip(1)
            .filter_map(|(index, ch)| {
                (!"ぁぃぅぇぉゃゅょっゎゕゖー".contains(ch) && !rest[..index].ends_with('っ'))
                    .then_some(index)
            })
            .collect();
        ends.push(run_end);
        let head = ends
            .into_iter()
            .rev()
            .find(|&end| is_common_reading(&rest[..end]));
        let mut end = head.unwrap_or(run_end);
        while let Some(particle) = PARTICLES
            .iter()
            .find(|particle| rest[end..].starts_with(*particle))
        {
            end += particle.len();
        }
        clauses.push(&rest[..end]);
        rest = &rest[end..];
    }
    clauses
}

/// Builds the clauses of a conversion. `hints` are `(reading, text)` clauses
/// from the system IME. They are used only when they add up to `reading`.
pub fn segments(reading: &str, hints: &[(String, String)], learned: &Learned) -> Vec<Segment> {
    let joined: String = hints.iter().map(|(reading, _)| reading.as_str()).collect();
    let clauses: Vec<(&str, Option<&str>)> = if !hints.is_empty() && joined == reading {
        hints
            .iter()
            .map(|(reading, text)| (reading.as_str(), Some(text.as_str())))
            .collect()
    } else {
        split_clauses(reading)
            .into_iter()
            .map(|clause| (clause, None))
            .collect()
    };
    let mut segments: Vec<Segment> = clauses
        .into_iter()
        .map(|(reading, best)| Segment {
            reading: reading.to_owned(),
            candidates: clause_candidates(reading, best, learned),
            selected: 0,
        })
        .collect();
    // A sentence that was written before leads as one clause. The ordinary
    // conversion stays among its candidates.
    let phrases = learned.exact(reading);
    if segments.len() > 1 && !phrases.is_empty() {
        let mut candidates: Vec<String> = phrases.into_iter().map(str::to_owned).collect();
        let ordinary: String = segments.iter().map(|segment| segment.text()).collect();
        for value in [ordinary, reading.to_owned()] {
            if !candidates.contains(&value) {
                candidates.push(value);
            }
        }
        segments = vec![Segment {
            reading: reading.to_owned(),
            candidates,
            selected: 0,
        }];
    }
    // A kaomoji or symbol made for the whole reading (にこにこ, さようなら) is
    // reachable from a single clause even when the words split apart.
    if segments.len() > 1 && symbols(reading).next().is_some() {
        let ordinary: String = segments.iter().map(|segment| segment.text()).collect();
        let mut candidates = vec![ordinary];
        for value in clause_candidates(reading, None, learned) {
            if !candidates.contains(&value) {
                candidates.push(value);
            }
        }
        segments = vec![Segment {
            reading: reading.to_owned(),
            candidates,
            selected: 0,
        }];
    }
    segments
}

#[cfg(test)]
mod tests {
    use super::{kana, reading_corrections};

    #[test]
    fn offers_dictionary_readings_for_a_mistyped_tail() {
        let (length, readings) = reading_corrections("きょうはこんぱんは").unwrap();
        assert_eq!(length, "こんぱんは".len());
        assert!(
            readings.iter().any(|reading| reading == "こんばんは"),
            "{readings:?}"
        );
        let (_, readings) = reading_corrections("ありがうと").unwrap();
        assert!(
            readings.iter().any(|reading| reading == "ありがとう"),
            "{readings:?}"
        );
        assert!(readings.len() <= super::MAX_CORRECTIONS);
    }

    #[test]
    fn leaves_correct_or_unfinished_readings_alone() {
        assert!(reading_corrections("きょうはこんばんは").is_none());
        // Still on its way to こんにちは.
        assert!(reading_corrections("こんに").is_none());
        assert!(reading_corrections("あい").is_none());
        assert!(reading_corrections("").is_none());
    }

    #[test]
    fn repeated_consonants_without_a_syllable_remain_literal() {
        for consonant in "bcdfghjklmnpqrstvwxyz".chars() {
            let input = consonant.to_string().repeat(3);
            assert_eq!(kana(&input, false), input);
            assert_eq!(kana(&input, true), input);
        }
        assert_eq!(kana("kitte", true), "きって");
        assert_eq!(kana("aaa", true), "あああ");
        assert_eq!(kana("nn", true), "ん");
    }
}
